using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using System.Text.Json;
using Microsoft.Data.SqlClient;
using Microsoft.Extensions.Configuration;
using Microsoft.IdentityModel.Tokens;
var root=Path.GetFullPath(args[0]); var cfg=new ConfigurationBuilder().AddJsonFile(Path.Combine(root,"laoo_api","appsettings.json")).AddJsonFile(Path.Combine(root,"laoo_api","local.json")).Build();
var row=File.ReadAllLines(Path.Combine(root,"build","sales_permission_after.txt")).First(x=>x.EndsWith("|09001|VIEW")).Split('|'); long company=long.Parse(row[0]), uid=long.Parse(row[1]);
await using var db=new SqlConnection(cfg.GetConnectionString("LaooDatabase")); await db.OpenAsync(); await using var cmd=new SqlCommand("SELECT C.PartnerID,P.ProjectID FROM dbo.TDSTCompanySetUp C CROSS JOIN dbo.TDADProject P WHERE C.CompanyID=@c AND P.ProjectCode=N'LAOO'",db); cmd.Parameters.AddWithValue("@c",company); await using var rd=await cmd.ExecuteReaderAsync(); await rd.ReadAsync(); long partner=rd.GetInt64(0), project=rd.GetInt64(1);
var claims=new[]{new Claim("user_type","COMPANY_USER"),new Claim("user_id",uid.ToString()),new Claim("company_id",company.ToString()),new Claim("partner_id",partner.ToString()),new Claim("project_id",project.ToString())};
var key=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(cfg["Jwt:SecretKey"]!)); var token=new JwtSecurityToken(cfg["Jwt:Issuer"],cfg["Jwt:Audience"],claims,DateTime.UtcNow.AddMinutes(-1),DateTime.UtcNow.AddMinutes(3),new SigningCredentials(key,SecurityAlgorithms.HmacSha256));
using var http=new HttpClient{BaseAddress=new Uri("http://127.0.0.1:5080/"),Timeout=TimeSpan.FromSeconds(25)}; http.DefaultRequestHeaders.Authorization=new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer",new JwtSecurityTokenHandler().WriteToken(token));
using var res=await http.GetAsync("api/navigation/projects"); res.EnsureSuccessStatusCode(); using var json=JsonDocument.Parse(await res.Content.ReadAsStringAsync()); var projects=json.RootElement.EnumerateArray().ToArray(); var trade=projects.Single(p=>p.GetProperty("projectCode").GetString()=="LAOO_TRADE"); var menus=trade.GetProperty("menuGroups").EnumerateArray().SelectMany(g=>g.GetProperty("items").EnumerateArray()); if(!menus.Any(i=>i.GetProperty("menuCode").GetString()=="09001")) throw new Exception("Sales menu missing"); Console.WriteLine("Live navigation contains separate sales project and menu.");
if (trade.GetProperty("projectName").GetString() != "ระบบขาย") throw new Exception("Incorrect sales project name");
Console.WriteLine("Live navigation displays the corrected sales name.");
if (trade.GetProperty("configuredMenuGroupCount").GetInt32()!=1) throw new Exception("Incorrect configured group count");
var core=projects.Single(p=>p.GetProperty("projectCode").GetString()=="LAOO");
if (core.GetProperty("configuredMenuGroupCount").GetInt32()<=1) throw new Exception("Core should retain multiple groups");
Console.WriteLine("API reports configured group counts for sales and core.");
await using var db2=new SqlConnection(cfg.GetConnectionString("LaooDatabase")); await db2.OpenAsync(); await using var roles=new SqlCommand("SELECT TOP (1) RG.RoleGroupID FROM dbo.TDADRoleGroup RG JOIN dbo.TDADProject P ON P.ProjectID=RG.ProjectID AND P.ProjectCode=N'LAOO' WHERE RG.CompanyID=@c AND RG.ScopeType=N'C' AND RG.IsActive=1 ORDER BY RG.RoleGroupID",db2); roles.Parameters.AddWithValue("@c",company); var role=await roles.ExecuteScalarAsync(); if(role is null) throw new Exception("No role available");
using var perms=await http.GetAsync($"api/company-role-permissions?roleGroupId={role}"); perms.EnsureSuccessStatusCode(); using var pd=JsonDocument.Parse(await perms.Content.ReadAsStringAsync()); var saleRows=pd.RootElement.EnumerateArray().Where(x=>x.GetProperty("menuGroupCode").GetString()=="09").ToArray(); if(saleRows.Length==0 || saleRows.Any(x=>x.GetProperty("configuredMenuGroupCount").GetInt32()!=1)) throw new Exception("Incorrect sales permissions group count"); Console.WriteLine("Permission API returns sales menu group metadata.");
